"""

from src.train import run_training

model, ds, edge_index, edge_attr, (X_te, Y_te), best_val = run_training(cfg)
torch.save(model.state_dict(), cfg["checkpoint_path"])
print("final val loss:", best_val)

"""## 7. Evaluate: topology recovery + robustness"""

from src.evaluate import evaluate_topology_recovery, robustness_sweep
from src.graph_builder import build_candidate_edges

edges = build_candidate_edges(ds.genes, tf_list=cfg["tf_list"], expr=ds.expr)
x_window = torch.tensor(X_te[0], dtype=torch.float32, device=edge_index.device)

topo_metrics = evaluate_topology_recovery(model, ds, edge_index, edge_attr, edges, x_window)
print("Topology recovery:", topo_metrics)

robustness_df = robustness_sweep(model, edge_index, edge_attr, X_te, Y_te,
                                  device=edge_index.device)
robustness_df.to_csv("robustness_results.csv", index=False)
print(robustness_df)

